// Build CHORD//SCOPE into one self-contained file: ./index.html
// (open it straight from disk, or let GitHub Pages serve it).
//
//   src/template.html   page, styles and markup, with /*PLACEHOLDER*/ slots
//   src/*.js            chord engine, score model + view, MIDI/MusicXML files, player, roll, app
//   src/keyboard3d.js   three.js keyboard, bundled here with esbuild (three is tree-shaken in)
//   src/*.json          glyph outlines and piano samples, generated by tools/*.py
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import * as esbuild from 'esbuild';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const read = (p) => fs.readFileSync(here(p), 'utf8');

const kb = await esbuild.build({
  entryPoints: [here('./src/keyboard3d.js')],
  bundle: true,
  format: 'iife',
  minify: true,
  target: 'es2022',
  legalComments: 'eof', // keeps the three.js MIT notice
  write: false,
  logLevel: 'warning',
});
const keyboard3d = kb.outputFiles[0].text.trim();

const pkg = JSON.parse(read('./package.json'));
const slots = [
  ['/*GLYPHS*/', read('./src/glyphs.json').trim()],
  ['/*ENGINE*/', read('./src/engine.js')],
  ['/*SCOREGLYPHS*/', read('./src/score_glyphs.json').trim()],
  ['/*SCOREMODEL*/', read('./src/score-model.js')],
  ['/*SCOREVIEW*/', read('./src/score-view.js')],
  ['/*KEYBOARD3D*/', keyboard3d],
  ['/*MIDIFILE*/', read('./src/midi-file.js')],
  ['/*MUSICXML*/', read('./src/musicxml.js')],
  ['/*PLAYER*/', read('./src/player.js')],
  ['/*ROLLVIEW*/', read('./src/roll-view.js')],
  ['/*PIANOSAMPLES*/', read('./src/piano_samples.json').trim()],
  ['/*APP*/', read('./src/app.js')],
];
let html = read('./src/template.html');
for (const [slot, code] of slots) {
  if (!html.includes(slot)) throw new Error('missing placeholder ' + slot);
  if (/<\/script/i.test(code)) throw new Error('script terminator inside ' + slot);
  html = html.replace(slot, () => code);
}
html = html
  .replace('<html lang="en">', `<html lang="en">\n<!-- CHORD//SCOPE ${pkg.version} · https://github.com/ScottieFox/chordscope · MIT License · third-party notices: THIRD_PARTY_NOTICES.md -->`)
  .replace('<script id="glyphs">', '<!-- Music glyph outlines derived from the Bravura and Petaluma fonts and text glyphs from Petaluma Script, (c) Steinberg Media Technologies GmbH, SIL Open Font License 1.1 -->\n<script id="glyphs">')
  .replace('<script type="application/json" id="piano-samples">', '<!-- Piano: Salamander Grand Piano V3 by Alexander Holm, CC BY 3.0 (https://creativecommons.org/licenses/by/3.0/) - velocity layer 8, trimmed and re-encoded as Ogg Vorbis -->\n<script type="application/json" id="piano-samples">')
  .replace('<script id="keyboard-3d">', '<!-- 3D keyboard: three.js r184 (c) 2010-2026 three.js authors, MIT License -->\n<script id="keyboard-3d">');

fs.writeFileSync(here('./index.html'), html);
console.log(`built index.html  ${(Buffer.byteLength(html) / 1024).toFixed(0)} KB  (three.js keyboard ${(keyboard3d.length / 1024).toFixed(0)} KB, piano samples ${(slots.find((x) => x[0] === '/*PIANOSAMPLES*/')[1].length / 1024).toFixed(0)} KB)`);
